class Tools:
    """OS-AutoFix Sandbox and Diagnostic Tools for Open-WebUI."""

    def list_scenarios(self) -> str:
        """Return available OS failure scenarios and descriptions."""
        from scenarios.registry import get_all_scenarios
        import json
        return json.dumps([{"name": s.name, "description": s.description} for s in get_all_scenarios()])

    def run_command(self, instance_id: str, command: str) -> str:
        """Execute command in target sandbox with timeout protection."""
        import subprocess
        res = subprocess.run(["incus", "exec", instance_id, "--", "bash", "-c", command], capture_output=True, text=True, timeout=15)
        return res.stdout + res.stderr
